import{_ as a,o as s,c as o,a2 as n}from"./chunks/framework.Di-jvWLj.js";const g=JSON.parse('{"title":"Agent Folders","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent-folders.md","filePath":"guide/agent-folders.md","lastUpdated":1793009019000}'),t={name:"guide/agent-folders.md"};function r(l,e,d,i,c,p){return s(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="agent-folders" tabindex="-1">Agent Folders <a class="header-anchor" href="#agent-folders" aria-label="Permalink to &quot;Agent Folders&quot;">​</a></h1><p>An app can load agents from a folder while it runs, next to the agents passed to <code>createApp({ agents })</code> or instead of them. Each subfolder is one agent; editing, adding or removing a folder reaches the engine, the cron channel, the HTTP routes and MCP on every replica, without a build or a rollout.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span>agents/</span></span>
<span class="line"><span>  triage/</span></span>
<span class="line"><span>    agent.ts             # the one required file: export default defineAgent({ name: &#39;triage&#39;, ... })</span></span>
<span class="line"><span>    prompt.md            # yours: agent.ts reads it</span></span>
<span class="line"><span>    tools/</span></span>
<span class="line"><span>      lookup-issue.ts    # yours: agent.ts imports it</span></span>
<span class="line"><span>  digest/</span></span>
<span class="line"><span>    agent.ts</span></span></code></pre></div><p>Folder code runs in the app&#39;s process with the app&#39;s full access (store, secrets, provided instances). Only people who may deploy the app should be able to write the folder.</p><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th></th></tr></thead><tbody><tr><td><code>CHAMVI_AGENTS_DIR</code></td><td><code>./agents</code> when it is a directory, else none</td><td>The agents dir, relative to the working directory or absolute</td></tr><tr><td><code>CHAMVI_AGENTS_POLL_MS</code></td><td><code>5000</code> (<code>DEFAULT_AGENTS_POLL_MS</code>)</td><td>How often the dir is checked for changes, 1 to <code>TIMER_MAX_MS</code></td></tr></tbody></table><p><code>createApp()</code> may get no <code>agents</code> at all, and the CLI needs no entry file: in a project holding only <code>agents/&lt;name&gt;/agent.ts</code>, <code>chamvi dev</code> and <code>chamvi start</code> run the default app with those agents. An app with no agent anywhere still starts and logs a warning. A <code>CHAMVI_AGENTS_DIR</code> that names no directory fails <code>start</code> and <code>run-job</code> (exit 2). <code>chamvi migrate</code> ignores the folder.</p><p>The built-in module <code>chamvi:agents</code> (<code>agentsModule()</code>) does the work: <code>start</code> and <code>run-job</code> load every folder before the engine starts, so the first queued run already finds its agent, and <code>start</code> then watches the dir until the app stops. <code>run-job</code> loads once and does not watch, so <code>chamvi run-job &lt;agent&gt;</code> works for a folder agent too; it never removes an agent whose folder it does not see (only <code>start</code> does), so a job pod without the agents volume cannot cancel the replicas&#39; runs.</p><p>The agents dir may live anywhere, also outside the app (a volume at <code>/data/agents</code>): <code>@chamvi/*</code>, <code>ai</code> and <code>@ai-sdk/*</code> always resolve to the copies the app itself uses, wherever the importing file is. Other packages resolve like Node resolves them, from the importing file upwards, so keep the dir inside the app&#39;s directory (for example <code>/app/agents</code> next to <code>/app/node_modules</code>) when folder code imports them.</p><h2 id="the-folder" tabindex="-1">The folder <a class="header-anchor" href="#the-folder" aria-label="Permalink to &quot;The folder&quot;">​</a></h2><p>An agent folder holds an <code>agent.ts</code>, and chamvi enforces nothing else. The folder name is the agent name (<code>^[a-z0-9]+(-[a-z0-9]+)*$</code>, at most 64 characters). <code>agent.ts</code> default-exports <code>defineAgent({ name, ... })</code>&#39;s result, whose <code>name</code> must equal the folder name (anything else is an error); a folder without <code>agent.ts</code> is reported as an issue (<code>&lt;name&gt;: has no agent.ts.</code>).</p><p>Everything else in the folder is the agent&#39;s own: <code>agent.ts</code> loads its tools, instructions, subscriptions and helpers with plain imports or file reads, organised however you like. <code>prompt.md</code> and <code>tools/</code> in the tree above are an example, not a convention.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// agents/triage/agent.ts: the one file chamvi reads; the name must match the folder name</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { readFileSync } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;node:fs&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { defineAgent, http } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/app&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { lookupIssue } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;./tools/lookup-issue.ts&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> default</span><span style="color:#E6DFDE;"> defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;triage&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model: </span><span style="color:#E7C58C;">&#39;anthropic/claude-sonnet-5-5&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // read on every load, so an edit of prompt.md reloads the agent like any other file</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: readFileSync(</span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> URL(</span><span style="color:#E7C58C;">&#39;./prompt.md&#39;</span><span style="color:#E6DFDE;">, </span><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;">.meta.url), </span><span style="color:#E7C58C;">&#39;utf8&#39;</span><span style="color:#E6DFDE;">),</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: { lookup_issue: lookupIssue },</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [http.on()],</span></span>
<span class="line"><span style="color:#E6DFDE;">    budget: { maxSteps: </span><span style="color:#E7C58C;">10</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// agents/triage/tools/lookup-issue.ts: the agent&#39;s own file, imported by agent.ts</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { defineTool } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/app&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { z } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;zod&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> const</span><span style="color:#E6DFDE;"> lookupIssue = defineTool({</span></span>
<span class="line"><span style="color:#E6DFDE;">    description: </span><span style="color:#E7C58C;">&#39;Reads an issue the agent saw before.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    inputSchema: z.object({ number: z.number().int().positive() }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> ({ number }, { context }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> (</span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> context.state.get(</span><span style="color:#E7C58C;">\`issue:</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">number</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">)) </span><span style="color:#FF7B84;">??</span><span style="color:#E6DFDE;"> { unknown: </span><span style="color:#FF7B84;">true</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>Folders in the agents dir whose name starts with <code>.</code> or <code>_</code> are skipped, so an <code>_archive/</code> folder is no agent (a <code>node_modules</code> folder is never an agent either, and refused, see <a href="#imports">Imports</a>).</p><h2 id="imports" tabindex="-1">Imports <a class="header-anchor" href="#imports" aria-label="Permalink to &quot;Imports&quot;">​</a></h2><p><code>agent.ts</code> may import its own files (relative imports, any depth) and packages installed in the app. jiti transpiles <code>agent.ts</code> and every <code>.ts</code> or <code>.mts</code> file it imports on every load, without a module cache, so a reload sees every edit; a file <code>agent.ts</code> reads itself (<code>readFileSync(new URL(&#39;./prompt.md&#39;, import.meta.url), &#39;utf8&#39;)</code>) is read again on every load too, and JSON imports are read fresh. Helpers must be TypeScript: Node caches a natively imported <code>.js</code>, <code>.mjs</code> or <code>.cjs</code> file for the life of the process, so a JavaScript file anywhere in the folder is a load error (<code>a JavaScript file is not reloaded fresh; write helpers as .ts or .mts.</code>).</p><p>Packages load natively, as the same instance the app uses, and <code>@chamvi/*</code>, <code>ai</code> and <code>@ai-sdk/*</code> resolve to the app&#39;s copies. That matters: a second copy of <code>@chamvi/core</code> would break context keys (<code>defineContextKey()</code> refuses a key of another copy), <code>instanceof</code> checks of chamvi errors and the tool context marker. So an agent folder and the agents dir never have a <code>node_modules</code> folder (a load error); a package folder code needs is installed in the app.</p><h2 id="load-errors" tabindex="-1">Load errors <a class="header-anchor" href="#load-errors" aria-label="Permalink to &quot;Load errors&quot;">​</a></h2><p>A folder that does not load never stops the app. A missing <code>agent.ts</code>, a syntax error, a missing default export, a definition <code>defineAgent()</code> refuses (a duplicate subscription id), a model string whose provider is not installed, a subscription naming no registered channel, a cron subscription the cron channel cannot schedule (a timezone or an expression it refuses), a <code>run_&lt;agent&gt;</code> MCP tool that cannot be built (an agent name above 60 characters with an <code>http.on()</code> subscription, a payload schema MCP cannot compile): the agent is reported as failed to load, with a message naming the file relative to the agents dir. Each module checks a folder agent before it is registered (the <code>AGENT_CHECKS</code> contributions), so a refused agent writes no marker and cancels nothing.</p><ul><li>The log gets <code>agent load failed</code> with the agent and the message.</li><li><code>GET /agents</code> lists it in <code>issues: [{ agent, message, at }]</code> next to <code>data</code>, and the <a href="/guide/ui">dashboard</a>&#39;s agents page shows a notice.</li><li>An agent that loaded before stays loaded with its previous code until the folder is valid again, and its runs go on. A broken folder is tried once per content: the next attempt comes with the next change.</li></ul><h2 id="live-reload" tabindex="-1">Live reload <a class="header-anchor" href="#live-reload" aria-label="Permalink to &quot;Live reload&quot;">​</a></h2><p>Each poll hashes every folder (sha256 over every file below it, dot-entries skipped), so a change to any file of the folder, also one <code>agent.ts</code> only reads, reloads the agent. A changed folder loads once two polls in a row see the same hash, so a change lands within two intervals and a tree that is still being copied is not loaded half-way: the load hashes the folder again before and after it reads it, and registers the agent only when both equal the stable hash (otherwise the next stable poll decides). A folder missing on two polls in a row is removed. When the agents dir itself is gone, or has no entry at all (the empty mount point of a volume that is not mounted), every agent stays loaded and nothing is removed until it is back; the boot removes no agent for such a dir either. To remove the last folder agent on purpose, leave any file in the dir (a <code>.keep</code>), so its empty listing counts.</p><p>To replace a folder at once, write the new tree next to it under a dot-prefixed name (skipped by the loader) and rename it over the old one.</p><h3 id="replacing-an-agent-cancels-its-runs" tabindex="-1">Replacing an agent cancels its runs <a class="header-anchor" href="#replacing-an-agent-cancels-its-runs" aria-label="Permalink to &quot;Replacing an agent cancels its runs&quot;">​</a></h3><p>A new version of an agent&#39;s code cancels the agent&#39;s unsettled runs (<code>queued</code>, <code>running</code>, <code>waiting</code>, <code>interrupted</code>) created before the change, then the new code takes over. Settled runs and their steps stay readable, also after the agent was removed. Plan changes with that in mind: an agent whose runs wait on approvals loses them on every edit.</p><ul><li><strong>Once across replicas.</strong> The store keeps one revision marker per folder agent (<code>{ agent, hash, changedAt }</code>, no code). The first replica that loads a new hash takes the store lock <code>agents:&lt;name&gt;</code>, cancels, and writes the marker; the others find the marker at their hash and only swap the code.</li><li><strong>First sight cancels nothing</strong>: a folder added to the dir has no marker yet.</li><li><strong>While the app was down</strong>: a folder changed while every replica was stopped cancels once at the next boot; a normal boot cancels nothing. A marker whose folder is gone at boot removes that agent.</li><li><strong>Removal</strong> cancels every unsettled run of the agent and deletes its marker; a replica that removes it later cancels the runs it created meanwhile. A replica that still has an older version leaves a newer marker (and its runs) alone.</li></ul><h2 id="several-replicas" tabindex="-1">Several replicas <a class="header-anchor" href="#several-replicas" aria-label="Permalink to &quot;Several replicas&quot;">​</a></h2><p>Every process sharing the store (replicas, <code>run-job</code> pods, a canary) must see byte-identical folders: mount one ReadWriteMany volume (NFS, CephFS, EFS) into each, or a ConfigMap (read-only is fine; chamvi never writes it). Baking the folder into the image works only while every process runs the same image: during a rolling deploy two images register two hashes, the last one to load moves the marker, and the other replicas stop running that agent until they are replaced. Each replica polls on its own, since inotify does not cross NFS, and nothing is relayed through the store, so replicas agree within about two poll intervals.</p><p>A replica whose folder did not change but whose marker another process moved or removed runs nothing of that agent and reports it as an issue (<code>another process sharing the store registered other content for this agent; ...</code>, logged as <code>agent revision moved</code>); it does not move the marker back, since two processes with different folders would cancel each other&#39;s runs. The issue clears once the folder and the marker match again.</p><p>During that window the store keeps them apart: a replica starts (and recovers) a run of a folder agent only while its loaded hash equals the stored marker, and a run of an agent it has not loaded at all (not seen yet, failed to load) stays <code>queued</code> for a replica that has it, instead of failing. A run created under the new hash is never cancelled by a replica that lags behind, since the cancel covers only runs created before the marker changed and happens once.</p><h2 id="code-agents-win" tabindex="-1">Code agents win <a class="header-anchor" href="#code-agents-win" aria-label="Permalink to &quot;Code agents win&quot;">​</a></h2><p>A folder named like an agent passed to <code>createApp({ agents })</code> is not loaded: it is reported as an issue (<code>a code agent has this name; the folder is not loaded.</code>), and the code agent stays as it is.</p><h2 id="without-the-app" tabindex="-1">Without the app <a class="header-anchor" href="#without-the-app" aria-label="Permalink to &quot;Without the app&quot;">​</a></h2><p>The loader is part of <code>@chamvi/app</code>&#39;s main entry, for tests and tools:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">function</span><span style="color:#E6DFDE;"> loadAgent(dir: string, options?: LoadAgentOptions): Promise&lt;LoadedAgent&gt;; </span><span style="color:#958A8B;">// throws InvalidAgentDefinitionError</span></span>
<span class="line"><span style="color:#FF7B84;">function</span><span style="color:#E6DFDE;"> loadAgents(root: string, options?: LoadAgentOptions): Promise&lt;LoadAgentsResult&gt;; </span><span style="color:#958A8B;">// never throws for a folder</span></span>
<span class="line"><span style="color:#FF7B84;">function</span><span style="color:#E6DFDE;"> listAgentFolders(root: string): Promise&lt;string[]&gt;;</span></span>
<span class="line"><span style="color:#FF7B84;">function</span><span style="color:#E6DFDE;"> hashAgentFolder(dir: string): Promise&lt;string&gt;;</span></span></code></pre></div><p>Registering an agent at runtime is the engine&#39;s: <code>engine.putAgent(agent, { revision? })</code> and <code>engine.removeAgent(name)</code> (see the <a href="/reference/#engine">core reference</a>).</p>`,37)])])}const u=a(t,[["render",r]]);export{g as __pageData,u as default};
